VALUES ('yang-guang', '杨广', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '隋炀帝，开运河、三征高句丽；江都时期仍为名义皇帝，与长安杨侑并存；江都兵变被杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/隋炀帝"}]'::jsonb, '炀皇帝', NULL, '隋炀帝')
