VALUES ('li-zhu-tang', '李柷', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '唐哀帝，朱温篡唐，唐亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐哀帝"}]'::jsonb, '哀帝', NULL, '唐哀帝')
