VALUES ('liu-jiyuan', '刘继元', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '刘钧养子，继刘继恩被杀后即位。北汉在北宋持续围攻下日益困窘，979年宋太宗亲征太原，刘继元出降，北汉亡，宋完成对中原与北方主要地区的统一。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘继元"}]'::jsonb, NULL, NULL, '北汉末帝')
